org.machanism.macha.core.commons.configurator.Configurator conf = getApplicationConfigurator();
org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", conf);
provider.instructions("You are a concise assistant.");
provider.prompt("Summarize the project architecture.");
java.lang.String answer = provider.perform();
provider.clear();

org.machanism.machai.ai.provider.impl.OpenAIProvider provider = new org.machanism.machai.ai.provider.impl.OpenAIProvider();
provider.init("gpt-4.1", getApplicationConfigurator());
provider.prompt("Write a release note.");
java.lang.String response = provider.perform();

org.machanism.machai.ai.provider.impl.AnthropicProvider provider = new org.machanism.machai.ai.provider.impl.AnthropicProvider();
provider.init("claude-3-5-sonnet", getApplicationConfigurator());
provider.prompt("Explain the provider abstraction.");
java.lang.String response = provider.perform();

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("None:log", getApplicationConfigurator());
provider.prompt("Smoke-test the provider lifecycle.");
java.lang.String response = provider.perform();

org.machanism.machai.ai.provider.impl.OpenAIProvider provider = new org.machanism.machai.ai.provider.impl.OpenAIProvider();
provider.init("text-embedding-3-small", getApplicationConfigurator());
java.util.List<java.lang.Double> embedding = provider.embedding("Machai provider abstraction", 1536L);

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("Tools:yaml", getApplicationConfigurator());
provider.addTools(new com.example.tools.ProjectTools(), null);
provider.prompt("tool: project_summary\nparams:\n  path: .");
java.lang.String result = provider.perform();

public final class com.example.tools.ProjectTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(name = "project_summary", description = "Summarizes supplied text.")
  public java.lang.String summarize(@org.machanism.machai.ai.tools.Param(name = "text", description = "Text to summarize") java.lang.String text) {
    return text == null ? "" : text;
  }
}

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", getApplicationConfigurator());
provider.prompt("Hello");
java.lang.String response = provider.perform();

public final class com.example.tools.ExampleFunctionTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(name = "echo", description = "Returns supplied text.")
  public java.lang.String echo(@org.machanism.machai.ai.tools.Param(name = "text", description = "Text to echo") java.lang.String text) { return text; }
}

# src/main/resources/META-INF/services/org.machanism.machai.ai.tools.FunctionTools
com.example.tools.ExampleFunctionTools

org.machanism.machai.ai.tools.FunctionToolsLoader loader = new org.machanism.machai.ai.tools.FunctionToolsLoader();
loader.applyTools(provider, null, com.example.Application.class);

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", getApplicationConfigurator());
provider.prompt("Use current public information and project tools to prepare a status report.");
java.lang.String result = provider.perform();
